package com.bank.corp.producer;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.util.Set;

@Component
public class SaltingKeyStrategy {

    @Value("${corp.salting.buckets}")
    private int buckets;

    @Value("#{'${corp.salting.hot-customers}'.split(',')}")
    private Set<String> hotCustomers;

    // Only HOT customers get a bucket suffix. Ordinary customers keep plain keys,
    // so they keep strict per-customer ordering and pay no merge cost.
    public String keyFor(String customerId, String orderId) {
        if (!hotCustomers.contains(customerId)) {
            return customerId;
        }
        // Salt by orderId so each ORDER stays in one bucket (order-level ordering kept),
        // while the customer's many orders spread across buckets (load spread).
        int bucket = Math.floorMod(orderId.hashCode(), buckets);
        return customerId + "-" + bucket;
    }
}
