package com.bank.corp.consumer;

import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;

@Component
@Slf4j
public class MergingOrderConsumer {

    // Per logical customer, buffer by sequence to reassemble a merged, ordered view.
    private final Map<String, TreeMap<Long, String>> perCustomer = new ConcurrentHashMap<>();

    @KafkaListener(topics = "corp.orders", groupId = "corp-order-view")
    public void onOrder(org.apache.kafka.clients.consumer.ConsumerRecord<String, String> rec) {
        String physicalKey = rec.key();                 // e.g. BIGCORP-2 or SAV2001
        String logicalCustomer = physicalKey.contains("-")
                ? physicalKey.substring(0, physicalKey.lastIndexOf('-'))
                : physicalKey;
        long seq = extractSeq(rec.value());             // producer-stamped global seq
        perCustomer.computeIfAbsent(logicalCustomer, k -> new TreeMap<>()).put(seq, rec.value());
        log.info("Buffered order for {} (bucket key {}) at seq {}", logicalCustomer, physicalKey, seq);
    }

    // Downstream read: merge all buckets for a customer into one ordered sequence.
    public Iterable<String> orderedViewFor(String logicalCustomer) {
        return perCustomer.getOrDefault(logicalCustomer, new TreeMap<>()).values();
    }

    private long extractSeq(String payload) {
        return Long.parseLong(payload.replaceAll(".*\"seq\":(\\d+).*", "$1"));
    }
}
