package com.bank.corp.demo;

import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class HotPartitionDemo {

    private static final Logger log = Logger.getLogger(HotPartitionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        int partitions = 6;
        int bigCorpOrders = 8000;     // 80% of 10000
        int otherOrders = 2000;

        log.info("=== Before: plain customerId keys (hot partition) ===");
        PartitionLoad plain = new PartitionLoad(partitions);
        for (int i = 0; i < bigCorpOrders; i++) plain.route("BIGCORP");
        for (int i = 0; i < otherOrders; i++) plain.route("CUST-" + (i % 50));
        plain.report(log);

        log.info("=== After: selective salting BIGCORP across 4 buckets ===");
        PartitionLoad salted = new PartitionLoad(partitions);
        SaltingKeyStrategy salt = new SaltingKeyStrategy(4, Set.of("BIGCORP"));
        for (int i = 0; i < bigCorpOrders; i++) salted.route(salt.keyFor("BIGCORP", "ORD-" + i));
        for (int i = 0; i < otherOrders; i++) salted.route(salt.keyFor("CUST-" + (i % 50), "ORD-x"));
        salted.report(log);

        log.info("=== Consumer trade-off: merge BIGCORP buckets for an ordered view ===");
        MergingConsumer consumer = new MergingConsumer();
        consumer.ingest("BIGCORP-0", 3, "orderC");
        consumer.ingest("BIGCORP-2", 1, "orderA");
        consumer.ingest("BIGCORP-1", 2, "orderB");
        log.info("Merged ordered BIGCORP view: " + consumer.merged("BIGCORP"));
    }
}

