class PartitionLoad {
    private final int[] counts;
    PartitionLoad(int partitions) { counts = new int[partitions]; }

    void route(String key) {
        int p = Math.floorMod(key.hashCode(), counts.length);
        counts[p]++;
    }

    void report(Logger log) {
        int max = 0, min = Integer.MAX_VALUE, total = 0;
        for (int c : counts) { max = Math.max(max, c); min = Math.min(min, c); total += c; }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < counts.length; i++) sb.append("p").append(i).append("=").append(counts[i]).append(" ");
        log.info("partition load: " + sb);
        double skew = (double) max / Math.max(1, (double) total / counts.length);
        if (skew > 2.0) log.severe(String.format("HOT PARTITION: max=%d is %.1fx the average", max, skew));
        else log.info(String.format("balanced: max=%d, min=%d (skew factor %.2f)", max, min, skew));
    }
}

// ─── Would be in SaltingKeyStrategy.java (demo copy) ───
class SaltingKeyStrategy {
    private final int buckets;
    private final Set<String> hot;
    SaltingKeyStrategy(int buckets, Set<String> hot) { this.buckets = buckets; this.hot = hot; }
    String keyFor(String customerId, String orderId) {
        if (!hot.contains(customerId)) return customerId;
        return customerId + "-" + Math.floorMod(orderId.hashCode(), buckets);
    }
}

// ─── Would be in MergingConsumer.java in a real project ───
class MergingConsumer {
    private final java.util.Map<String, java.util.TreeMap<Long, String>> buf = new java.util.HashMap<>();
    void ingest(String physicalKey, long seq, String payload) {
        String logical = physicalKey.substring(0, physicalKey.lastIndexOf('-'));
        buf.computeIfAbsent(logical, k -> new java.util.TreeMap<>()).put(seq, payload);
    }
    java.util.Collection<String> merged(String logical) {
        return buf.getOrDefault(logical, new java.util.TreeMap<>()).values();
    }
}

